WITH cleaned AS (SELECT id, session_id, event_type, page, event_time, duration_sec, DATE_FORMAT(event_time, 'MMM yyyy') AS event_time_label, LOWER(event_type) AS event_type_lower FROM web_events WHERE page IS NOT NULL AND page IS DISTINCT FROM '/home'), flagged AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_session FROM cleaned), islands AS (SELECT id, session_id, event_type, event_time, event_type_lower, SUM(is_new_session) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT DATE_TRUNC('WEEK', event_time) AS week_start, APPROX_PERCENTILE(burst_id, 0.5) AS burst_id_p50, COUNT(*) FILTER (WHERE event_type = 'page_view') AS page_view_rows, COUNT(DISTINCT id) AS distinct_ids FROM islands GROUP BY DATE_TRUNC('WEEK', event_time)
